 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Horizontal bands consist of left and right row segments separated by
    # a gap. Extend each segment's color vertically away from its source row,
    # using the isolated vertical marker column on that side as its axis.
    bands = []
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v]
        if len(nz) >= 4 and len(set(row[c] for c in nz)) <= 2:
            # identify distinct contiguous runs in nonzero cells, ignoring gaps
            runs=[]; start=prev=nz[0]
            for c in nz[1:]:
                if c != prev+1:
                    runs.append((start,prev)); start=c
                prev=c
            runs.append((start,prev))
            if len(runs)==2 and runs[0][1] < runs[1][0]:
                bands.append((r,runs[0],runs[1]))
    markers=[]
    for c in range(w):
        cells=[r for r in range(h) if grid[r][c]]
        if len(cells)>=2 and len(set(grid[r][c] for r in cells))==1:
            markers.append((c,grid[cells[0]][c],min(cells),max(cells)))
    # Each color band is paired to the vertical marker in its corresponding
    # left or right region; color each column's span from marker toward band.
    for r,(a,b),(d,e) in bands:
        for c0,c1,color in ((a,b,grid[r][a]),(d,e,grid[r][d])):
            candidates=[m for m in markers if c0<=m[0]<=c1]
            if not candidates:
                # The marker axis may be adjacent to the run's gap boundary.
                candidates=[m for m in markers if abs(m[0]-(c1+1))<=1 or abs(m[0]-(c0-1))<=1]
            if candidates:
                c=min(candidates,key=lambda m:abs(m[0]-(c0+c1)/2))[0]
                for rr in range(min(r, h-1), -1, -1):
                    if rr==r: continue
                    if grid[rr][c] == 0: g[rr][c]=color
    return g
