 "content": "def transform(grid):
    # Draw the grid of horizontal and vertical rays indicated by row bars and
    # isolated marker columns. Horizontal bar gaps take the bar's color;
    # each column marker extends from its first appearance upward, adopting
    # the color of any horizontal bar crossing it.
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Fill gaps between consecutive nonzero cells on bar rows.
    for r in range(h):
        nz=[c for c,v in enumerate(grid[r]) if v]
        if len(nz)>=4:
            for a,b in zip(nz,nz[1:]):
                if b-a>1:
                    for c in range(a+1,b):
                        g[r][c]=grid[r][a]
    # Identify vertical marker columns (vertical runs or isolated cells).
    cols=[c for c in range(w) if sum(grid[r][c]!=0 for r in range(h))>=2]
    for c in cols:
        # Extend upward from lowest nonzero point; use the nearest bar above
        # to determine color where a bar crosses the marker column.
        points=[r for r in range(h) if grid[r][c]]
        if not points: continue
        top=min(points)
        below=max(points)
        for r in range(top):
            # Color from the nearest horizontal patterned row beneath this cell
            bars=[rr for rr in range(r+1,h) if sum(grid[rr][x]!=0 for x in range(w))>=4 and (grid[rr][c]!=0 or (c>0 and c+1<w and grid[rr][c-1] and grid[rr][c+1]))]
            if bars:
                rr=min(bars)
                g[r][c]=grid[rr][c-1] if c>0 and grid[rr][c-1] else grid[rr][c+1]
    return g
