    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Locate row bands and their missing cells. Row gap locations are
    # projected vertically only when a matching vertical marker exists.
    bars=[]
    for r in range(h):
        nz=[c for c,v in enumerate(grid[r]) if v]
        if len(nz)<4: continue
        gaps=[]
        for a,b in zip(nz,nz[1:]):
            if b-a>1:
                # Bar gap may span multiple cells; fill based on neighboring
                # side color only when the row pattern is a horizontal line.
                for c in range(a+1,b):
                    g[r][c]=grid[r][a]
                    gaps.append((c,grid[r][a]))
        if gaps: bars.append((r,gaps))
    for c in range(w):
        marks=[r for r in range(h) if grid[r][c]]
        # A vertical line marker below rows: fill above it with color from
        # nearest bar gap at this column, if such gap exists.
        if not marks: continue
